package com.bookstore.application.sequences;
public final class SequenceService { public static final String BOOK_ID_SEQUENCE_KEY="book-id", ORDER_ID_SEQUENCE_KEY="order-id"; private final SequenceRepository repo; public SequenceService(SequenceRepository repo){this.repo=repo;} public long allocateNextValue(String key){if(key==null||key.isBlank())throw new IllegalArgumentException("Sequence key is required."); var s=repo.getByKey(key); if(!s.key().equals(key))throw new IllegalStateException("Sequence repository returned key '"+s.key()+"' for requested key '"+key+"'."); return repo.allocateSequence(s);} public int allocateNextBookId(){long v=allocateNextValue(BOOK_ID_SEQUENCE_KEY); if(v>Integer.MAX_VALUE)throw new IllegalStateException("No more book IDs can be allocated because the sequence is exhausted."); return (int)v;} public String allocateNextOrderId(){return Long.toString(allocateNextValue(ORDER_ID_SEQUENCE_KEY));} }
